import os, json, sqlite3, secrets, hashlib, hmac, csv, io, time
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
from http.cookies import SimpleCookie
from datetime import datetime, timezone

DB=os.environ.get('DATABASE_PATH','entrelinhas.sqlite3'); PORT=int(os.environ.get('PORT','8000')); ADMIN=os.environ.get('ADMIN_PASSWORD',''); SECRET=os.environ.get('SESSION_SECRET','')
if not SECRET: SECRET=secrets.token_hex(32)

def db():
 c=sqlite3.connect(DB); c.row_factory=sqlite3.Row; c.execute('PRAGMA foreign_keys=ON'); return c

def token():
 raw=f'{int(time.time())+86400}:{secrets.token_hex(12)}'; sig=hmac.new(SECRET.encode(),raw.encode(),hashlib.sha256).hexdigest(); return raw+'.'+sig

def valid(t):
 try:
  raw,sig=t.rsplit('.',1); exp=int(raw.split(':')[0]); return exp>time.time() and hmac.compare_digest(sig,hmac.new(SECRET.encode(),raw.encode(),hashlib.sha256).hexdigest())
 except: return False

class H(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def send(self,status,obj,ctype='application/json; charset=utf-8',extra=None):
  data=obj.encode() if isinstance(obj,str) else json.dumps(obj,ensure_ascii=False).encode(); self.send_response(status); self.send_header('Content-Type',ctype); self.send_header('Content-Length',str(len(data))); self.send_header('X-Content-Type-Options','nosniff'); self.send_header('Cache-Control','no-store');
  for k,v in (extra or {}).items(): self.send_header(k,v)
  self.end_headers(); self.wfile.write(data)
 def body(self): return json.loads(self.rfile.read(int(self.headers.get('Content-Length',0)) or 0) or b'{}')
 def admin(self):
  ck=SimpleCookie(); ck.load(self.headers.get('Cookie','')); return 'session' in ck and valid(ck['session'].value)
 def do_GET(self):
  p=urlparse(self.path).path
  if p=='/': return self.send(200,HTML,'text/html; charset=utf-8')
  if p=='/api/questions':
   with db() as c: rows=c.execute('select * from questions where active=1').fetchall()
   return self.send(200,[dict(r,options=json.loads(r['options'])) for r in rows])
  if p.startswith('/api/admin/') and not self.admin(): return self.send(401,{'error':'Autenticação necessária'})
  if p=='/api/admin/me': return self.send(200,{'ok':True})
  if p=='/api/admin/entries':
   with db() as c: rows=c.execute('select id,submitted,name,version,complete,payload from entries order by submitted desc').fetchall()
   return self.send(200,[dict(r,payload=json.loads(r['payload'])) for r in rows])
  if p=='/api/admin/questions':
   with db() as c: rows=c.execute('select * from questions order by category,id').fetchall()
   return self.send(200,[dict(r,options=json.loads(r['options'])) for r in rows])
  if p=='/api/admin/export':
   with db() as c: rows=c.execute('select * from entries order by submitted desc').fetchall()
   out=io.StringIO(); w=csv.writer(out); w.writerow(['ID','Data UTC','Nome','Versão','Concluída','Pergunta ID','Categoria','Pergunta','Resposta'])
   for e in rows:
    for a in json.loads(e['payload']): w.writerow([e['id'],e['submitted'],e['name'],e['version'],e['complete'],a.get('id'),a.get('category'),a.get('question'),a.get('answer','')])
   return self.send(200,out.getvalue(),'text/csv; charset=utf-8',{'Content-Disposition':'attachment; filename="entrelinhas-respostas.csv"'})
  return self.send(404,{'error':'Não encontrado'})
 def do_POST(self):
  p=urlparse(self.path).path; b=self.body()
  if p=='/api/login':
   if not ADMIN: return self.send(503,{'error':'Configure ADMIN_PASSWORD no ambiente antes de habilitar o painel.'})
   if not hmac.compare_digest(str(b.get('password','')),ADMIN): return self.send(401,{'error':'Senha incorreta'})
   t=token(); return self.send(200,{'ok':True},extra={'Set-Cookie':f'session={t}; HttpOnly; SameSite=Strict; Path=/; Max-Age=86400'+('; Secure' if self.headers.get('X-Forwarded-Proto')=='https' else '')})
  if p=='/api/logout': return self.send(200,{'ok':True},extra={'Set-Cookie':'session=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0'})
  if p=='/api/submit':
   answers=b.get('answers',[])
   if not isinstance(answers,list) or len(answers)>30: return self.send(400,{'error':'Respostas inválidas'})
   with db() as c:
    known={r['id']:r for r in c.execute('select * from questions')}
    clean=[]
    for a in answers:
     q=known.get(a.get('id'))
     if q and q['active']: clean.append({'id':q['id'],'category':q['category'],'question':q['text'],'answer':str(a.get('answer',''))[:5000]})
    eid=secrets.token_urlsafe(12); now=datetime.now(timezone.utc).isoformat()
    c.execute('insert into entries values(?,?,?,?,?,?)',(eid,now,str(b.get('name',''))[:80],1,json.dumps(clean,ensure_ascii=False),1))
   return self.send(201,{'id':eid,'submitted':now})
  if p.startswith('/api/admin/') and not self.admin(): return self.send(401,{'error':'Autenticação necessária'})
  if p=='/api/admin/questions':
   q=b; qid=q.get('id') or 'q'+secrets.token_hex(5)
   if not q.get('text') or not q.get('category'): return self.send(400,{'error':'Categoria e pergunta são obrigatórias'})
   with db() as c:
    c.execute('INSERT INTO questions(id,category,text,type,options,required,active,created) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET category=excluded.category,text=excluded.text,type=excluded.type,options=excluded.options,required=excluded.required,active=excluded.active',(qid,str(q['category'])[:80],str(q['text'])[:700],q.get('type','open'),json.dumps(q.get('options',[]),ensure_ascii=False),int(bool(q.get('required')),),int(bool(q.get('active',True))),datetime.now(timezone.utc).isoformat()))
   return self.send(200,{'id':qid})
  if p=='/api/admin/delete':
   with db() as c: c.execute('delete from entries where id=?',(b.get('id'),))
   return self.send(200,{'ok':True})
  if p=='/api/admin/note':
   with db() as c: c.execute('insert into notes values(?,?) on conflict(entry_id) do update set body=excluded.body',(b.get('id'),str(b.get('body',''))[:10000]))
   return self.send(200,{'ok':True})
  return self.send(404,{'error':'Não encontrado'})
 def do_PUT(self): self.do_POST()

