with db() as c:
 c.execute('CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY, category TEXT, text TEXT, type TEXT, options TEXT, required INTEGER DEFAULT 0, active INTEGER DEFAULT 1, created TEXT)')
 c.execute('CREATE TABLE IF NOT EXISTS entries(id TEXT PRIMARY KEY, submitted TEXT, name TEXT, version INTEGER, payload TEXT, complete INTEGER)')
 c.execute('CREATE TABLE IF NOT EXISTS notes(entry_id TEXT PRIMARY KEY, body TEXT, FOREIGN KEY(entry_id) REFERENCES entries(id) ON DELETE CASCADE)')
 if c.execute('select count(*) from questions').fetchone()[0]==0:
  for i,(cat,q,typ,opts) in enumerate(QUESTIONS): c.execute('INSERT INTO questions VALUES(?,?,?,?,?,?,?,?)',(f'q{i+1:02}',cat,q,typ,json.dumps(opts,ensure_ascii=False),0,1,datetime.now(timezone.utc).isoformat()))

HTML= r'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#100d14"><title>ENTRELINHAS</title><style>
:root{--bg:#100d14;--panel:#19141e;--line:#332839;--muted:#b9aebb;--text:#f6eff8;--lilac:#c7a4e8;--purple:#8b63a9}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 10%,#33213d 0,transparent 38%),radial-gradient(ellipse at 0 90%,#211729 0,transparent 40%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;min-height:100vh}button,input,textarea,select{font:inherit}button{cursor:pointer}.wrap{max-width:960px;margin:auto;padding:24px}.nav{display:flex;justify-content:space-between;align-items:center;padding:15px 0}.logo{letter-spacing:.24em;font-size:12px;color:#d9c3e9}.quiet{background:transparent;color:var(--muted);border:1px solid var(--line);border-radius:99px;padding:9px 15px}.hero{min-height:78vh;display:grid;align-content:center;position:relative;overflow:hidden}.eyebrow,.category{font-size:11px;text-transform:uppercase;letter-spacing:.2em;color:var(--lilac)}h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(56px,10vw,102px);letter-spacing:.08em;margin:18px 0}.lead{font-family:Georgia,serif;color:#dfd2e4;font-size:clamp(21px,3vw,30px);max-width:620px;line-height:1.4}.sub{color:var(--muted);line-height:1.8;max-width:560px}.primary{background:linear-gradient(120deg,#cfb3e8,#a77ac9);border:0;color:#1b1220;border-radius:99px;padding:15px 24px;font-weight:650;box-shadow:0 8px 30px #9a6db52d}.start{margin-top:24px}.stars{position:absolute;right:8%;top:18%;width:250px;height:250px;border:1px solid #a97cc52b;border-radius:50%;box-shadow:0 0 0 33px #a97cc50a,0 0 0 67px #a97cc507}.stars:before,.stars:after{content:'✦';position:absolute;color:#d8b9f4;font-size:14px;left:18%;top:27%;text-shadow:105px 75px #d8b9f4,150px -30px #d8b9f4}.stars:after{content:'';width:7px;height:7px;background:#dec9f2;border-radius:50%;top:49%;left:72%;box-shadow:-111px -88px 0 1px #d5b8ed,54px -119px 0 #d5b8ed}.card{background:#18141dd9;border:1px solid #382c40;border-radius:24px;padding:clamp(22px,5vw,48px);box-shadow:0 24px 80px #0004}.progress{height:3px;background:#342a39;border-radius:10px;margin:18px 0 32px}.progress i{height:100%;display:block;background:var(--lilac);transition:width .35s;border-radius:10px}.question{font:clamp(24px,4vw,35px)/1.32 Georgia,serif;margin:22px 0 28px}.answer{width:100%;min-height:125px;background:#100d14;border:1px solid #46384c;border-radius:14px;color:var(--text);padding:16px;resize:vertical;outline:none}.answer:focus,input:focus{border-color:var(--lilac)}.option{display:block;width:100%;text-align:left;background:#100d14;border:1px solid #46384c;color:var(--text);padding:15px 17px;margin:10px 0;border-radius:13px;transition:.2s}.option:hover,.option.sel{border-color:var(--lilac);background:#2a2032}.actions{display:flex;justify-content:space-between;gap:12px;margin-top:24px;align-items:center}.micro{font-size:12px;color:var(--muted)}.namefield{width:100%;padding:13px 15px;background:#100d14;color:var(--text);border:1px solid #46384c;border-radius:12px}.hidden{display:none!important}.adminwrap{max-width:1120px}.grid{display:grid;grid-template-columns:1fr 2fr;gap:20px}.list button{width:100%;text-align:left;margin:5px 0;padding:13px;border:1px solid var(--line);background:#15111a;color:var(--text);border-radius:10px}.entry{padding:15px 0;border-bottom:1px solid var(--line)}.entry p{line-height:1.65;margin:8px 0}.tag{font-size:11px;color:var(--lilac)}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.tools input,.tools select{background:#100d14;color:var(--text);border:1px solid var(--line);padding:10px;border-radius:10px}.small{padding:10px 15px}.notice{color:var(--muted);font-size:13px;line-height:1.6}.adminform{display:grid;gap:12px}.adminform input,.adminform textarea,.adminform select{background:#100d14;border:1px solid var(--line);border-radius:9px;padding:11px;color:var(--text)}@media(max-width:700px){.wrap{padding:16px}.stars{right:-98px;top:12%;transform:scale(.75)}.hero{min-height:80vh}.grid{grid-template-columns:1fr}.list{max-height:260px;overflow:auto}.card{border-radius:19px}.actions .primary{padding:13px 18px}}
</style><body><div class="wrap"><header class="nav"><div class="logo">E N T R E L I N H A S</div><button class="quiet" id="adminLink">Área privada</button></header><main id="app"></main></div><script>
const app=document.querySelector('#app');let qs=[], selected=[],idx=0,answers={},name='';const $=s=>document.querySelector(s);const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opt={}){let r=await fetch(url,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});let d=r.headers.get('content-type')?.includes('json')?await r.json():await r.text();if(!r.ok)throw Error(d.error||'Falha na solicitação');return d}
function home(){app.innerHTML=`<section class="hero"><div class="stars"></div><div class="eyebrow">UMA EXPERIÊNCIA DE CONEXÃO</div><h1>ENTRELINHAS</h1><div class="lead">Todo mundo tem respostas.<br>Poucos sabem fazer as perguntas certas.</div><p class="sub">Uma conversa consigo e com o mundo — feita de hipóteses, escolhas e detalhes que dizem mais do que parecem.</p><button class="primary start" id="begin">Começar a experiência&nbsp; ↗</button><p class="micro">15 perguntas · sem cadastro · no seu ritmo</p></section>`;$('#begin').onclick=start}
async function start(){try{qs=await api('/api/questions')}catch(e){alert(e.message);return}const groups={};qs.forEach(q=>(groups[q.category]??=[]).push(q));let cats=Object.keys(groups).sort(()=>Math.random()-.5);selected=[];while(selected.length<18&&cats.length){for(let c of cats){if(groups[c].length&&selected.length<18)selected.push(groups[c].splice(Math.random()*groups[c].length|0,1)[0])}cats=cats.filter(c=>groups[c].length)}selected.sort(()=>Math.random()-.5);idx=-1;answers={};try{let saved=JSON.parse(sessionStorage.getItem('entrelinhas')||'{}');if(saved.answers&&confirm('Encontramos uma experiência não enviada neste navegador. Deseja retomá-la?')){selected=saved.selected;answers=saved.answers;name=saved.name||'';idx=Math.min(saved.idx,selected.length-1)}}catch{}renderIntro()}
function persist(){sessionStorage.setItem('entrelinhas',JSON.stringify({selected,answers,name,idx}))}
function renderIntro(){app.innerHTML=`<section class="card"><div class="category">Antes de começar</div><h2 class="question">Como podemos chamar você?</h2><p class="sub">Pode ser um apelido — é totalmente opcional.</p><input class="namefield" id="participant" maxlength="80" placeholder="Seu nome ou apelido (opcional)" value="${escapeHtml(name)}"><p class="notice">Suas respostas são enviadas de forma privada à pessoa que compartilhou esta experiência. Não há pontuação nem diagnóstico.</p><div class="actions"><button class="quiet" id="home">Voltar</button><button class="primary" id="go">Começar ↗</button></div></section>`;$('#home').onclick=home;$('#go').onclick=()=>{name=$('#participant').value;idx=Math.max(0,idx);persist();renderQ()}}
function renderQ(){let q=selected[idx];if(!q)return finish();let val=answers[q.id]||'';app.innerHTML=`<section class="card"><div class="micro">${idx+1} de ${selected.length}</div><div class="progress"><i style="width:${(idx+1)/selected.length*100}%"></i></div><div class="category">${escapeHtml(q.category)}</div><div class="question">${escapeHtml(q.text)}</div>${q.type==='choice'?q.options.map(o=>`<button class="option ${val===o?'sel':''}" data-v="${escapeHtml(o)}">${escapeHtml(o)}</button>`).join(''):`<textarea id="answer" class="answer" maxlength="5000" placeholder="Escreva o que vier à mente…">${escapeHtml(val)}</textarea>`}<div class="actions"><button class="quiet" id="back">← Anterior</button><span class="micro">Pode pular esta pergunta</span><button class="primary" id="next">${idx===selected.length-1?'Concluir':'Continuar'} →</button></div></section>`;if(q.type==='choice')document.querySelectorAll('.option').forEach(b=>b.onclick=()=>{answers[q.id]=b.dataset.v;persist();renderQ()});$('#back').onclick=()=>{capture();if(idx>0){idx--;persist();renderQ()}else renderIntro()};$('#next').onclick=()=>{capture();if(idx<selected.length-1){idx++;persist();renderQ()}else submit()};if($('#answer'))$('#answer').oninput=()=>{answers[q.id]=$('#answer').value;persist()}}
function capture(){let q=selected[idx];if(q&&$('#answer'))answers[q.id]=$('#answer').value;persist()}
async function submit(){let btn=$('#next');if(btn){btn.disabled=true;btn.textContent='Enviando…'}try{let r=await api('/api/submit',{method:'POST',body:JSON.stringify({name,answers:selected.filter(q=>answers[q.id]).map(q=>({id:q.id,answer:answers[q.id]}))})});sessionStorage.removeItem('entrelinhas');app.innerHTML=`<section class="hero"><div class="eyebrow">EXPERIÊNCIA CONCLUÍDA</div><h1 style="font-size:clamp(45px,8vw,76px)">Obrigado${name?', '+escapeHtml(name):''}.</h1><div class="lead">Às vezes, a resposta mais interessante é a conversa que começa depois.</div><p class="sub">Sua participação foi registrada com segurança. Código: <strong>${escapeHtml(r.id)}</strong></p><button class="quiet" onclick="home()">Voltar ao início</button></section>`}catch(e){alert('Não foi possível enviar. Suas respostas continuam salvas neste navegador. '+e.message);if(btn){btn.disabled=false;btn.textContent='Tentar novamente'}}}
function finish(){submit()}
$('#adminLink').onclick=admin;
async function admin(){app.innerHTML=`<section class="card"><div class="category">Acesso reservado</div><h2 class="question">Área administrativa</h2><form id="login" class="adminform"><input type="password" id="pw" placeholder="Senha administrativa" required><button class="primary">Entrar</button></form><p class="notice">A autenticação depende da senha configurada no servidor. Os dados não são expostos publicamente.</p></section>`;$('#login').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify({password:$('#pw').value})});dashboard()}catch(err){alert(err.message)}}}
let entries=[], activeEntry=null, allQuestions=[];
async function dashboard(){try{[entries,allQuestions]=await Promise.all([api('/api/admin/entries'),api('/api/admin/questions')])}catch(e){return admin()}drawDash()}
function drawDash(){app.innerHTML=`<div class="adminwrap"><div class="category">ENTRELINHAS · PRIVADO</div><h2 style="font:36px Georgia">Painel de respostas</h2><div class="tools"><input id="search" placeholder="Pesquisar nome ou resposta…"><button class="quiet small" id="csv">Exportar CSV</button><button class="quiet small" id="manage">Perguntas (${allQuestions.length})</button><button class="quiet small" id="logout">Sair</button></div><div class="grid"><div class="list">${entries.map(e=>`<button data-id="${e.id}"><b>${escapeHtml(e.name||'Participante anônimo')}</b><br><span class="micro">${new Date(e.submitted).toLocaleString('pt-BR')} · ${e.payload.length} respostas</span></button>`).join('')||'<p class="notice">Ainda não há participações.</p>'}</div><section class="card" id="detail"><p class="notice">Selecione uma participação para ler as respostas. Os resumos abaixo contabilizam categorias respondidas.</p>${summary()}</section></div></div>`;document.querySelectorAll('.list button').forEach(b=>b.onclick=()=>showEntry(b.dataset.id));$('#csv').onclick=()=>location.href='/api/admin/export';$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});admin()};$('#manage').onclick=manageQuestions;$('#search').oninput=()=>{let s=$('#search').value.toLowerCase();document.querySelectorAll('.list button').forEach(b=>b.classList.toggle('hidden',!b.textContent.toLowerCase().includes(s)||!entries.find(e=>e.id===b.dataset.id)?.payload.some(a=>a.answer.toLowerCase().includes(s))))}}
function summary(){let counts={};entries.forEach(e=>e.payload.forEach(a=>counts[a.category]=(counts[a.category]||0)+1));return `<div class="entry"><b>Resumo por categoria</b>${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<p><span class="tag">${escapeHtml(k)}</span> · ${v} respostas</p>`).join('')||'<p class="micro">Sem dados ainda.</p>'}</div><p class="notice">Leitura das Entrelinhas: use as respostas citadas como evidência e trate padrões como hipóteses, não diagnósticos. Não há inferência automatizada.</p>`}
function showEntry(id){activeEntry=entries.find(e=>e.id===id);let e=activeEntry;$('#detail').innerHTML=`<div class="category">${new Date(e.submitted).toLocaleString('pt-BR')} · ${escapeHtml(e.id)}</div><h3>${escapeHtml(e.name||'Participante anônimo')}</h3>${e.payload.map(a=>`<div class="entry"><div class="tag">${escapeHtml(a.category)}</div><p><b>${escapeHtml(a.question)}</b></p><p>${escapeHtml(a.answer)||'<span class="micro">Sem resposta</span>'}</p></div>`).join('')}<div class="tools"><button class="quiet small" id="del">Excluir participação</button><button class="quiet small" id="noteBtn">Leitura das Entrelinhas</button></div><div id="analysis" class="hidden"><p class="notice">Anote observações e cite as respostas que as fundamentam. Separe declaração literal de interpretação possível; evite diagnósticos ou conclusões definitivas.</p><textarea id="note" class="answer" placeholder="Observações privadas…"></textarea><button class="primary small" id="saveNote">Salvar nota</button></div>`;$('#del').onclick=async()=>{if(confirm('Excluir permanentemente esta participação?')){await api('/api/admin/delete',{method:'POST',body:JSON.stringify({id})});entries=entries.filter(x=>x.id!==id);drawDash()}};$('#noteBtn').onclick=()=>$('#analysis').classList.toggle('hidden');$('#saveNote').onclick=async()=>{await api('/api/admin/note',{method:'POST',body:JSON.stringify({id,body:$('#note').value})});alert('Nota salva.')}}
async function manageQuestions(){let data=await api('/api/admin/questions');app.innerHTML=`<section><div class="category">GERENCIAR BANCO</div><h2 style="font:36px Georgia">Perguntas</h2><button class="quiet" id="backDash">← Painel</button><div class="grid" style="margin-top:20px"><div class="list">${data.map(q=>`<button data-q="${q.id}"><b>${escapeHtml(q.category)}</b><br><span class="micro">${escapeHtml(q.text).slice(0,80)} · ${q.active?'ativa':'inativa'}</span></button>`).join('')}</div><form id="qform" class="card adminform"><input id="qid" type="hidden"><input id="cat" placeholder="Categoria" required><textarea id="qt" placeholder="Texto da pergunta" required></textarea><select id="type"><option value="open">Resposta aberta</option><option value="choice">Múltipla escolha</option></select><input id="opts" placeholder="Alternativas, separadas por |"><label><input type="checkbox" id="active" checked> Ativa</label><button class="primary">Salvar pergunta</button><button type="button" class="quiet" id="newq">Nova pergunta</button></form></div></section>`;$('#backDash').onclick=dashboard;$('#newq').onclick=()=>$('#qform').reset();document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{let q=data.find(x=>x.id===b.dataset.q);$('#qid').value=q.id;$('#cat').value=q.category;$('#qt').value=q.text;$('#type').value=q.type;$('#opts').value=q.options.join('|');$('#active').checked=!!q.active});$('#qform').onsubmit=async e=>{e.preventDefault();await api('/api/admin/questions',{method:'POST',body:JSON.stringify({id:$('#qid').value||undefined,category:$('#cat').value,text:$('#qt').value,type:$('#type').value,options:$('#opts').value.split('|').map(x=>x.trim()).filter(Boolean),active:$('#active').checked})});alert('Pergunta salva');manageQuestions()}}
home();
</script></body></html>'''
if __name__=='__main__':
 print(f'ENTRELINHAS listening on 0.0.0.0:{PORT}; ADMIN_PASSWORD '+('configured' if ADMIN else 'NOT configured'))
 HTTPServer(('0.0.0.0',PORT),H).serve_forever()
